import os, json
from pathlib import Path
root=Path('.')
exclude={'.git','build','out','.vs','.cache','CMakeFiles','vcpkg_installed'}
summary={}
for top in ['include','src','tests','docs','.github','.gsd']:
    p=root/top
    counts={'files':0,'dirs':0,'ext':{}}
    if p.exists():
        for dirpath, dirnames, filenames in os.walk(p):
            dirnames[:] = [d for d in dirnames if d not in exclude]
            counts['dirs']+=len(dirnames)
            for f in filenames:
                counts['files']+=1
                ext=Path(f).suffix or '<none>'
                counts['ext'][ext]=counts['ext'].get(ext,0)+1
    summary[top]=counts
print('Top-level inventory:')
for k,v in summary.items():
    print(f"{k}: {v['files']} files, {v['dirs']} dirs, ext={dict(sorted(v['ext'].items()))}")
print('\nSelected files:')
patterns=[]
for sub in ['include/libbsa','src/formats','src/detail','src/texture','tests/unit','tests/package-consumer','tests/fixtures/generated','docs']:
    p=root/sub
    if p.exists():
        files=sorted(str(x).replace('\\','/') for x in p.rglob('*') if x.is_file())
        print(f'[{sub}] {len(files)} files')
        for x in files[:80]: print('  '+x)
        if len(files)>80: print(f'  ... +{len(files)-80} more')

