  libbsa::result<void> fail(libbsa::error_code code, std::string message)
  {
    return libbsa::error{code, std::move(message)};
  }

  std::string host_path_string(const std::filesystem::path &path)
  {
    const auto utf8 = path.u8string();
    return {reinterpret_cast<const char *>(utf8.data()), utf8.size()};
  }

  std::vector<std::byte> bytes_from_text(std::string_view text)
  {
    std::vector<std::byte> bytes;
    bytes.reserve(text.size());
    for (const char ch : text)
    {
      bytes.push_back(static_cast<std::byte>(static_cast<unsigned char>(ch)));
    }
    return bytes;
  }

  std::vector<std::byte> repeated_bytes(std::uint8_t seed, std::size_t count)
  {
    std::vector<std::byte> result;
    result.reserve(count);
    for (std::size_t index = 0; index < count; ++index)
    {
      result.push_back(static_cast<std::byte>(static_cast<std::uint8_t>(seed + index)));
    }
    return result;
  }

  libbsa::result<void> write_binary_file(const std::filesystem::path &path, std::span<const std::byte> values)
  {
    std::error_code fs_error;
    std::filesystem::create_directories(path.parent_path(), fs_error);
    if (fs_error)
    {
      return fail(libbsa::error_code::io_error, "failed to create package-consumer source directory: " + fs_error.message());
    }

    std::ofstream output{path, std::ios::binary | std::ios::trunc};
    if (!output.good())
    {
      return fail(libbsa::error_code::io_error, "failed to open package-consumer source file: " + path.string());
    }

    output.write(reinterpret_cast<const char *>(values.data()), static_cast<std::streamsize>(values.size()));
    if (!output.good())
    {
      return fail(libbsa::error_code::io_error, "failed to write package-consumer source file: " + path.string());
    }

    return {};
  }

  std::vector<std::byte> build_tiny_bc1_dds_dxt10_source()
  {
    byte_buffer writer;
    writer.ascii4("DDS ");
    for (const auto value : {124U, 0x0002100FU, 16U, 16U, 0U, 0U, 1U})
    {
      writer.u32(value);
    }
    for (std::uint32_t index = 0; index < 11U; ++index)
    {
      writer.u32(0U);
    }

    // The package consumer owns this tiny DXT10 DDS shape so the installed-package
    // smoke never reaches into source-tree fixture directories at runtime.
    for (const auto value : {32U, 0x00000004U, dds_fourcc_dx10, 0U, 0U, 0U, 0U, 0U, dds_caps_texture, 0U, 0U, 0U, 0U})
    {
      writer.u32(value);
    }
    for (const auto value : {dxgi_format_bc1_unorm, dds_resource_dimension_texture2d, 0U, 1U, 0U})
    {
      writer.u32(value);
    }

    const auto payload = repeated_bytes(0x52U, 16U * 8U);
    writer.raw(std::span<const std::byte>{payload.data(), payload.size()});
    return writer.bytes;
  }

